<script setup lang="ts">
import {ref} from 'vue'
import {onShow,onHide} from '@dcloudio/uni-app'
import {request,navigate,token,type Row} from '../../api/platform'
import {abandonLogin} from '../../features/auth'
import LoginSheet from '../../components/LoginSheet.vue'
import PageState from '../../components/PageState.vue'
const tab=ref('replacement'),rows=ref<Row[]>([]),counts=ref<Record<string,number>>({replacement:0,keyword:0,instant:0}),error=ref(''),notice=ref(''),loading=ref(false),busy=ref(false),signedIn=ref(false),page=ref(1),total=ref(0),instantAuthorized=ref(false)
const filters:Record<string,string>={replacement:'eventType=REPLACED',keyword:'mode=DAILY&targetType=KEYWORD',instant:'mode=INSTANT'}
const emptyText:Record<string,string>={replacement:'暂无更替提醒。关注的信息被更替时会出现在这里。',keyword:'暂无关键词提醒。在某个关键词上单独开启强提醒后，该词有新信息时会出现在这里。',instant:'暂无及时提醒。'}
async function load(){signedIn.value=!!token();if(!signedIn.value){rows.value=[];return}loading.value=true;error.value='';notice.value='';try{const result=await request('GET','/api/v1/me/reminders/changes?page='+page.value+'&size=20&'+filters[tab.value]);rows.value=result.items;total.value=result.total;const c=await request<Record<string,number>>('GET','/api/v1/me/reminders/change-counts');for(const key of Object.keys(filters))counts.value[key]=Number(c[key]||0);const s=await request('GET','/api/v1/me/reminders/settings');instantAuthorized.value=Boolean(s.permissions&&s.permissions[0]&&s.permissions[0].instantAuthorized)}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function switchTab(value:string){if(loading.value||busy.value)return;tab.value=value;page.value=1;void load()}
async function dismiss(row:Row){if(busy.value)return;busy.value=true;error.value='';try{await request('DELETE','/api/v1/me/reminders/changes/'+row.id,{});notice.value='已从提醒盒子移除';await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
onShow(load);onHide(abandonLogin)
</script><template><view class="page"><view class="hero"><text class="title">强提醒</text></view><view v-if="!signedIn" class="card"><text>登录后管理强提醒</text><button role="button" @click="navigate('login')">登录</button></view><template v-else><view v-if="tab==='instant'&&!instantAuthorized" class="card"><text class="card-title">订阅授权已用完</text><text class="muted">及时提醒按次授权，一次授权对应一次发送。要重新接收及时提醒，请重新授权。</text><button role="button" @click="navigate('notification-settings')">去重新授权</button></view><view class="segmented"><button role="button" :class="{active:tab==='replacement'}" @click="switchTab('replacement')">更替 {{ counts.replacement }}</button><button role="button" :class="{active:tab==='keyword'}" @click="switchTab('keyword')">关键词 {{ counts.keyword }}</button><button role="button" :class="{active:tab==='instant'}" @click="switchTab('instant')">及时 {{ counts.instant }}</button></view><text v-if="notice" class="muted">{{ notice }}</text><PageState :busy="loading" :error="error" :empty="!rows.length&&!loading" :empty-text="emptyText[tab]" @retry="load"/><view v-for="row in rows" :key="row.id" class="card"><text class="card-title" @click="navigate('article','?id='+row.articleId)">{{ row.title||'内容更新' }}</text><text class="muted">{{ row.eventType==='REPLACED'?'内容已被更替':'有新信息' }} · {{ row.createdAt }}</text><view class="actions"><button role="button" class="quiet" :disabled="busy" @click="dismiss(row)">不再提醒</button></view></view><view class="actions" v-if="total>20"><button role="button" :disabled="page===1||loading" @click="page--;load()">上一页</button><text>{{ page }}</text><button role="button" :disabled="page*20>=total||loading" @click="page++;load()">下一页</button></view><view class="bottom-actions"><button role="button" @click="navigate('notification-rules')">我关注的强提醒</button><button role="button" class="quiet" @click="navigate('notification-settings')">日常提醒时段</button></view></template><LoginSheet/></view></template>
